"""Registry of shipments by route."""

_ALL = []
_BY_KEY = None


def reset():
    """Forget every registered shipment."""
    global _BY_KEY
    del _ALL[:]
    _BY_KEY = None


def register(shipment):
    """Add one shipment to the registry."""
    _ALL.append(shipment)


def find(route):
    """Return the shipments registered under this route."""
    global _BY_KEY
    if _BY_KEY is None:
        _BY_KEY = {}
        for x in _ALL:
            _BY_KEY.setdefault(x.route, []).append(x)
    return _BY_KEY.get(route, [])


def route_names(shipments):
    """Return the distinct route values, in first-seen order."""
    names = []
    for x in shipments:
        if x.route not in names:
            names.append(x.route)
    return names

